/**
 * DV-3 regression obligations and the DV-4 reference gate.
 *
 * A confirmed failing test becomes a protected obligation only when the operator authorises it: nothing in the agent's
 * tool surface calls `authoriseObligation`; only operator commands do. The original failure record is immutable, so a
 * later minimisation keeps what was first seen. Each later verifier attempt of the obligation's command is a replay.
 * An edit that removes, skips or thins the obligation's test is recorded (never silently allowed, never blocked here).
 *
 * Limits: a replay says the verifier's output did or did not name the test as failing; a verifier that never runs the
 * test passes it vacuously, which Nexus cannot see. Pure data and pure functions; the agent owns persistence.
 */
import type { ObjectiveLedger, VerificationAttempt } from "./objective.js";

}

/**
 * DV-4 gate: a behavioural reference (previous revision, golden cases) may be declared only by the operator, and only
 * for a requirement the operator wrote. The differential itself is NOT implemented: this records authority only.
 */
export function authoriseReference(ledger: ObjectiveLedger, req: { authority: "operator"; requirementId: string; reference: string; at?: string }): Authorisation {
  requireOperator(req.authority);
  const r = ledger.requirements.find((x) => x.id === req.requirementId);
  if (!r) return { ok: false, reason: `no requirement ${req.requirementId}` };
  if (r.source === "model") return { ok: false, reason: `${r.id} was added by the model, so it cannot name a reference` };
  const refs = (ledger.references ??= []);
  const prior = refs.find((x) => x.requirementId === r.id);
  if (prior) prior.reference = req.reference;
  else refs.push({ requirementId: r.id, reference: req.reference, authorisedAt: req.at ?? now() });
  return { ok: true, id: r.id };
}

export function differentialStatus(ledger: ObjectiveLedger, requirementId: string): { state: "no-reference" | "authorised-not-run"; reference?: string } {
  const ref = ledger.references?.find((x) => x.requirementId === requirementId);
  return ref ? { state: "authorised-not-run", reference: ref.reference } : { state: "no-reference" };
}

/** How agreement with a reference is worded: finite cases are never reported as equivalence. */
export function agreementStatement(testedInputs: number): string {
  return `Agrees with the reference on ${testedInputs} tested input${testedInputs === 1 ? "" : "s"}; this is not equivalence and says nothing about untested inputs.`;
}
    }
  }
  const failed = report.findings.some((f) => f.status === "fail");
  return reply("doctor", renderDoctorText(report), !failed);
}

/**
 * `/requirements`: the acceptance requirements of the current objective. `accept <id>...` is the operator's authority
 * to let a requirement the agent descoped count as done; the agent cannot do this itself. The same holds for the
 * regression-obligation and reference verbs (DV-3/DV-4): `obligate <attempt> <test>` promotes a confirmed failing test,
 * `minimise <RO> <attempt> <test>` narrows it keeping the original record, `retire <RO>` ends it, `reference <R> <ref>`
 * names the behavioural reference an operator requirement is checked against.
 */
async function requirements({ host, args }: SlashContext): Promise<SlashOutcome> {
  const { acceptDescoping, requirementRows } = await import("../core/objective.js");
  const ledger = host.app.getAgent().getObjective();
  if (!ledger) return reply("requirements", "No objective is being tracked yet.");
  const [verb, ...ids] = args.split(/\s+/).filter(Boolean);
  let note = "";
  if (verb === "clear") {
    const dropped = host.app.getAgent().clearObjective();
    host.saveSession();
    const open = dropped ? requirementRows(dropped).filter(([, v]) => !/^(IMPLEMENTED|VERIFIED|DESCOPED \(accepted\))/.test(v)).map(([id]) => id) : [];
    return reply("requirements", `The objective is cleared${open.length ? ` (unresolved when cleared: ${open.join(", ")})` : ""}; your next message starts a new one.`);
  }
  if (verb === "accept") {
    if (!ids.length) return reply("requirements", "Name the requirements to accept, e.g. /requirements accept R2.", false);
    const { accepted, refused } = acceptDescoping(ledger, ids);
    if (accepted.length) host.saveSession();
    note = `${accepted.length ? `Accepted the descoping of ${accepted.join(", ")}.` : ""}${refused.length ? ` Not descoped (nothing to accept): ${refused.join(", ")}.` : ""}\n\n`;
  } else if (verb === "obligate" || verb === "minimise" || verb === "retire" || verb === "reference") {
    const ro = await import("../core/regression_obligations.js");
    const attemptAt = (i: number) => Number(ids[i]);
    const rest = (i: number) => ids.slice(i).join(" ");
    let result: { ok: true; id: string } | { ok: false; reason: string };
    if (verb === "obligate" && Number.isInteger(attemptAt(0)) && rest(1)) result = ro.authoriseObligation(ledger, { authority: "operator", attempt: attemptAt(0), testName: rest(1) });
    else if (verb === "minimise" && ids[0] && Number.isInteger(attemptAt(1)) && rest(2)) result = ro.minimiseObligation(ledger, ids[0], { attempt: attemptAt(1), testName: rest(2) });
    else if (verb === "retire" && ids[0]) result = ro.retireObligation(ledger, ids[0]);
    else if (verb === "reference" && ids[0] && rest(1)) result = ro.authoriseReference(ledger, { authority: "operator", requirementId: ids[0], reference: rest(1) });
    else return reply("requirements", "Usage: /requirements obligate <attempt> <test name> | minimise <RO> <attempt> <test name> | retire <RO> | reference <R> <reference>", false);
    if (!result.ok) return reply("requirements", `Not done: ${safeTerminal(result.reason)}`, false);
    host.saveSession();
    return reply("requirements", `${verb} recorded for ${result.id}.`);
  } else if (verb) {
    return reply("requirements", "Usage: /requirements [accept <id>...|clear|obligate|minimise|retire|reference]", false);
  }
  const rows = requirementRows(ledger);
  if (!rows.length) return reply("requirements", `${note}The objective is a single request; no separate acceptance requirements were listed.`);
  return reply("requirements", `${note}${rows.map(([id, value]) => `${id.padEnd(4)} ${value}`).join("\n")}`);
}

